// Extract message data
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

// Check if it's a valid message
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    // CRITICAL: Must preserve array positions for Node-RED routing!
    // Do NOT use .filter() - it removes nulls and breaks routing
    return [null, null, null, null, answerCallback];
}

// Store chat ID
if (!flow.get('lights_telegram_chat_ids')) {
    flow.set('lights_telegram_chat_ids', []);
}
const chatIds = flow.get('lights_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('lights_telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Only handle lights-specific commands
if (!command.startsWith('/lights_')) {
    // CRITICAL: Must preserve array positions for Node-RED routing!
    // Do NOT use .filter() - it removes nulls and breaks routing
    return [null, null, null, null, answerCallback];
}

const requestId = Date.now().toString(36) + Math.random().toString(36).substr(2);
node.warn(`[${requestId}] Garden Lights Command: ${command} from chat ${chatId}`);

// Prepare message
msg.requestId = requestId;
msg.chatId = chatId;
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// CRITICAL: Initialize array with null positions for ALL 5 outputs
// Node-RED uses array INDEX to route to specific wires
// output[0] → lights_on handler
// output[1] → lights_off handler
// output[2] → status handler
// output[3] → help handler
// output[4] → callback answer
let output = [null, null, null, null, null];

// Route to appropriate handler
switch(command) {
    case '/lights_on':
        output[0] = msg;
        output[4] = answerCallback;
        break;
    case '/lights_off':
        output[1] = msg;
        output[4] = answerCallback;
        break;
    case '/lights_status':
        output[2] = msg;
        output[4] = answerCallback;
        break;
    case '/lights_help':
        output[3] = msg;
        output[4] = answerCallback;
        break;
    default:
        // Unknown lights command, only send callback
        output[4] = answerCallback;
        break;
}

// CRITICAL: Return FULL array with nulls preserved!
// DO NOT USE .filter(m => m !== null) - it breaks routing!
return output;

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

node.warn(`[${msg.requestId}] Turning all garden lights ON`);

return [
    { payload: 'ON' },
    {
        payload: {
            chatId: msg.chatId,
            type: 'message',
            content: '💡 All garden lights turned *ON*',
            options: {
                parse_mode: 'Markdown'
            }
        }
    }
];

node.warn(`[${msg.requestId}] Turning all garden lights OFF`);

return [
    { payload: 'OFF' },
    {
        payload: {
            chatId: msg.chatId,
            type: 'message',
            content: '💡 All garden lights turned *OFF*',
            options: {
                parse_mode: 'Markdown'
            }
        }
    }
];

// Send the same command to all 16 lights
const command = msg.payload;
const messages = [];

// GardenAutomationLights (Relays 1-12)
for (let i = 1; i <= 12; i++) {
    messages.push({
        topic: `GardenAutomationLights/CMD/Relay${i}`,
        payload: command
    });
}

// frontHousePower (POWER1-4)
for (let i = 1; i <= 4; i++) {
    messages.push({
        topic: `cmnd/frontHousePower/POWER${i}`,
        payload: command
    });
}

return [messages];

node.warn(`[${msg.requestId}] Getting garden lights status`);

// Get state from GLOBAL context (shared across all flows)
const state = global.get('garden_lights_state') || {};

// Build status message
let statusText = '💡 *Garden Lights Status*\n\n';

// Lights 1-12 (GardenAutomationLights)
statusText += '*GardenAutomationLights:*\n';
for (let i = 1; i <= 12; i++) {
    const status = state[`light_${i}`] || 'UNKNOWN';
    const icon = status === 'ON' ? '🟢' : status === 'OFF' ? '⚫' : '❓';
    statusText += `${icon} Light ${i}: ${status}\n`;
}

// Lights 13-16 (frontHousePower)
statusText += '\n*Front House Power:*\n';
for (let i = 13; i <= 16; i++) {
    const status = state[`light_${i}`] || 'UNKNOWN';
    const icon = status === 'ON' ? '🟢' : status === 'OFF' ? '⚫' : '❓';
    statusText += `${icon} Light ${i}: ${status}\n`;
}

// Count lights
const lights = Object.values(state);
const onCount = lights.filter(s => s === 'ON').length;
const offCount = lights.filter(s => s === 'OFF').length;
const unknownCount = 16 - onCount - offCount;

statusText += `\n*Summary:* ${onCount} ON | ${offCount} OFF | ${unknownCount} Unknown`;

const inlineKeyboard = {
    inline_keyboard: [
        [{ text: '🟢 Turn All ON', callback_data: '/lights_on' }, { text: '⚫ Turn All OFF', callback_data: '/lights_off' }],
        [{ text: '🔄 Refresh Status', callback_data: '/lights_status' }]
    ]
};

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: statusText,
    options: {
        parse_mode: 'Markdown',
        reply_markup: inlineKeyboard
    }
};

return msg;

node.warn(`[${msg.requestId}] Garden lights help requested`);

const helpText = `💡 *Garden Lights Control*\n\n` +
    `*Available Commands:*\n` +
    `🟢 \`/lights_on\` - Turn all 16 lights ON\n` +
    `⚫ \`/lights_off\` - Turn all 16 lights OFF\n` +
    `📊 \`/lights_status\` - Get status of all lights\n` +
    `❓ \`/lights_help\` - Show this help\n\n` +
    `*Hardware:*\n` +
    `• Lights 1-12: GardenAutomationLights (12-relay)\n` +
    `• Lights 13-16: frontHousePower (4-relay)\n\n` +
    `*Quick Actions* ⬇️`;

const inlineKeyboard = {
    inline_keyboard: [
        [{ text: '🟢 All ON', callback_data: '/lights_on' }, { text: '⚫ All OFF', callback_data: '/lights_off' }],
        [{ text: '📊 Status', callback_data: '/lights_status' }],
        [{ text: '🏠 Main Menu', callback_data: '/help' }]
    ]
};

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: helpText,
    options: {
        parse_mode: 'Markdown',
        reply_markup: inlineKeyboard
    }
};

return msg;

